from typing import List

class Solution:
    def hasIncreasingSubarrays(self, nums: List[int], k: int) -> bool:
        n = len(nums)
        # Iterate through all possible starting positions for the first subarray.
        # The first subarray starts at index i and ends at i + k - 1.
        # The second subarray starts at index i + k and ends at i + 2k - 1.
        # We need to check if both subarrays are strictly increasing.
        # Valid range for i is 0 to n - 2k.

        for i in range(n - 2 * k + 1):
            # Check if the first subarray nums[i : i+k] is strictly increasing
            # A subarray is strictly increasing if nums[j] < nums[j+1] for all j in the range.
            is_first_increasing = True
            for j in range(i, i + k - 1):
                if nums[j] >= nums[j + 1]:
                    is_first_increasing = False
                    break

            if is_first_increasing:
                # Check if the second subarray nums[i+k : i+2k] is strictly increasing
                is_second_increasing = True
                for j in range(i + k, i + 2 * k - 1):
                    if nums[j] >= nums[j + 1]:
                        is_second_increasing = False
                        break

                if is_second_increasing:
                    return True

        return False

class Solution:
    def smallestNumber(self, n: int) -> int:
        x = 1
        while x < n:
            x = (x << 1) + 1
        return x
